@admin_bp.route("/audit", methods=["GET"])
def audit_log():
    """Most recent audit log entries."""
    session = get_session()
    events = (
        session.query(AuditLog).order_by(AuditLog.created_at.desc()).limit(100).all()
    )
    return jsonify(
        [
            {"id": e.id, "user_id": e.user_id, "action": e.action}
            for e in events
        ]
    )

def require_role(minimum_role: str):
    """Require at least the given role (user < manager < admin)."""

    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            user = get_current_user()
            if user is None:
                return jsonify({"error": "authentication required"}), 401
            if ROLE_RANK.get(user.role, 0) < ROLE_RANK.get(minimum_role, 99):
                return jsonify({"error": "insufficient role"}), 403
            g.current_user = user
            return fn(*args, **kwargs)

        return wrapper

    return decorator

findings.suggested_fix:
Restore the @require_role("admin") decorator on the audit_log view so the endpoint enforces authentication and the admin role, e.g.:

